32	void createDataCopyIfNeeded(Operation* op)
33	{
34	    for (auto& use : op->getUses()) {
35	        auto copyOp = dyn_cast<ascendc::DataCopyOp>(use.getOwner());
36	        if (!copyOp || copyOp.getDirection() != ascendc::CopyDirection::ubuf_gm)
37	            return;
38	        OpBuilder builder(op);
39	        ascir::ConstantOpBuilder consts(builder);
40	        auto type = cast<ascendc::BaseTensorType>(use.get().getType());
41	        auto dst = builder.create<ascendc::LocalTensorAutoOp>(
42	            op->getLoc(), type, /*input*/ false,
43	            /*output*/ true, ValueRange{});
44	        builder.setInsertionPointAfter(op);
45	        Value calCount = consts.i64(type.getNumElements());
46	        builder.create<ascendc::DataCopyL2Op>(op->getLoc(), dst, use.get(), calCount);
47	        copyOp.setSrc(dst);
48	    }
49	}
50	
51	void setInOutTensors(func::FuncOp funcOp)
52	{
53	    funcOp.walk([](ascendc::LocalTensorAutoOp op) {
54	        bool input = false;
55	        bool output = false;
56	        for (Operation* user : op->getUsers()) {
57	            if (auto copyOp = dyn_cast<ascendc::DataCopyOp>(user)) {
58	                auto dir = copyOp.getDirection();
59	                if (dir == ascendc::CopyDirection::gm_ubuf) {
60	                    input = true;
61	                    continue;
62	                }
63	                if (dir == ascendc::CopyDirection::ubuf_gm) {
64	                    output = true;
65	                    continue;
66	                }
67	            }
68	        }
69	        op.setInput(input);
70	        op.setOutput(output);
71	    });
72	    funcOp.walk([](scf::ForOp op) { createDataCopyIfNeeded(op); });
73	    funcOp.walk([](scf::IfOp op) { createDataCopyIfNeeded(op); });
74	}
75	
76	void fixInOutTensor(func::FuncOp& funcOp)
77	{
78	    funcOp.walk([](ascendc::LocalTensorAutoOp inTensor) {
79	        if (!inTensor.getInput() || inTensor.getOutput())
80	            return;
81	        auto loc = inTensor.getLoc();
82	        OpBuilder builder(inTensor);
83	        auto tensorType = inTensor.getResult().getType();
84	        inTensor.setOutput(false);
85	        for (auto& use : inTensor->getUses()) {
86	            auto* owner = use.getOwner();
87	            auto copyOp = dyn_cast<ascendc::DataCopyOp>(owner);
88	            if (!copyOp || copyOp.getDirection() != ascendc::CopyDirection::ubuf_gm)
89	                return builder.setInsertionPoint(owner);
90	            ascir::ConstantOpBuilder consts(builder);
91	            Value calCount = consts.i64(tensorType.getNumElements());
92	            auto outTensor = builder.create<ascendc::LocalTensorAutoOp>(
93	                loc, tensorType, /*input*/ false,
94	                /*output*/ true, ValueRange{});
95	            builder.create<ascendc::DataCopyL2Op>(loc, outTensor, inTensor, calCount);
96	            owner->setOperand(use.getOperandNumber(), outTensor);
97	        }
98	    });
99	}
