109	        fixInOutTensor(funcOp);
110	        MLIRContext* context = &getContext();
111	        RewritePatternSet patterns(context);
112	        ascendc::LocalTensorAutoOp::getCanonicalizationPatterns(patterns, context);
113	        if (applyPatternsAndFoldGreedily(funcOp, std::move(patterns)).failed()) {
114	            signalPassFailure();
115	            return;
116	        }
